def gen(rng):
    def fmt(g):
        return f'{len(g)} {len(g[0])}\n' + '\n'.join(' '.join(map(str, row)) for row in g)
    def rnd(r, c, lo, hi):
        return [[rng.randint(lo, hi) for _ in range(c)] for _ in range(r)]
    tests = [fmt([[9, 0, 2, 0, 1], [0, 1, 1, 1, 0], [2, 0, 0, 0, 0]]), fmt([[5]]), fmt([[-5]]),
             fmt([[1, 2, 3, 4]]), fmt([[1], [2], [3], [4]]), fmt([[-1, -2, -3], [-4, -5, -6]]),
             fmt([[0, 0], [0, 0]]), fmt([[1, -9, 1], [-9, -9, -9], [1, -9, 1]])]
    for _ in range(14):
        r, c = rng.randint(1, 6), rng.randint(1, 6)
        tests.append(fmt(rnd(r, c, -9, 9)))
    for _ in range(4):
        r, c = rng.randint(1, 5), rng.randint(1, 5)
        tests.append(fmt(rnd(r, c, 0, 9)))
    tests.append(fmt(rnd(300, 300, -1000, 1000)))
    tests.append(fmt(rnd(300, 300, -1000, -1)))
    tests.append(fmt(rnd(300, 300, 0, 1000)))
    return tests
